    name="triplet_margin_loss_cuda",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["triplet_margin_loss_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Triplet Margin Loss implemented with a single fused custom CUDA kernel.

    Matches torch.nn.TripletMarginLoss defaults: p=2.0, eps=1e-6, swap=False,
    reduction='mean'.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self.p = 2.0
        self.eps = 1e-6

    def forward(self, anchor, positive, negative):
        return _module.triplet_margin_loss_forward(
            anchor, positive, negative, self.margin, self.p, self.eps
        )

